def load_reports():
    if not DATA_FILE.exists():
        return pd.DataFrame(columns=REPORT_COLUMNS)
    try:
        df = pd.read_csv(DATA_FILE, dtype=str).fillna("")
    except (pd.errors.EmptyDataError, pd.errors.ParserError):
        return pd.DataFrame(columns=REPORT_COLUMNS)
    for column in REPORT_COLUMNS:
        if column not in df.columns:
            df[column] = ""

    # Remove the old water-bottle demonstration record from the visible dataset.
    item = df["ItemName"].astype(str).str.strip().str.lower()
    building = df["Building"].astype(str).str.strip().str.lower()
    location = df["Location"].astype(str).str.strip().str.lower()
    class_name = df["Class"].astype(str).str.strip().str.lower()
    description = df["Description"].astype(str).str.strip().str.lower()
    legacy_test = (
        item.eq("water bottle")
        & building.eq("girls building")
        & (location.eq("11k") | class_name.eq("11k"))
    )
    if legacy_test.any():
        df = df.loc[~legacy_test].copy()
        # Also clean the CSV when it is writable, so the test record stays gone.
        try:
            df[REPORT_COLUMNS].to_csv(DATA_FILE, index=False)
        except OSError:
            pass

    return df[REPORT_COLUMNS]


def save_report(report, uploaded_photo):
    if uploaded_photo is not None:
        ext = Path(uploaded_photo.name).suffix.lower()
        image_name = f"{uuid.uuid4().hex}{ext}"
        image_path = IMAGE_DIR / image_name
        image_path.write_bytes(uploaded_photo.getbuffer())
        report["Photo"] = str(image_path)
    else:
        report["Photo"] = ""
    pd.DataFrame([report], columns=REPORT_COLUMNS).to_csv(
        DATA_FILE, mode="a", header=not DATA_FILE.exists(), index=False
    )


def valid_rss_email(email):
    email = email.strip().lower()
    return email.endswith("@rawdalsaleheen.edu.kw") and len(email.split("@", 1)[0]) > 0


# Password verification for the resolve action only. No password is stored in plain text.
_RESOLVE_SALT = 'rss-resolve-v1-2026'
_RESOLVE_PASSWORD_HASH = 'a1aa1cecd176b33cd87b3d6b93bd466871749930deaa67d3f88f7950d5dbe0eb'

def valid_resolve_password(password):
    candidate = hashlib.pbkdf2_hmac(
        "sha256", password.encode("utf-8"), _RESOLVE_SALT.encode("utf-8"), 310000
    )
    return hmac.compare_digest(candidate, bytes.fromhex(_RESOLVE_PASSWORD_HASH))


def resolve_report(report_id):
    """Remove a resolved report from the active listings and delete its saved photo."""
    if not DATA_FILE.exists():
        return False
    try:
        df = pd.read_csv(DATA_FILE, dtype=str).fillna("")
    except (pd.errors.EmptyDataError, pd.errors.ParserError):
        return False
    if "ID" not in df.columns:
        return False

    match = df["ID"].astype(str) == str(report_id)
    if not match.any():
        return False

    if "Photo" in df.columns:
        for photo_path in df.loc[match, "Photo"].astype(str):
            if photo_path:
                try:
                    photo = Path(photo_path)
                    if photo.exists() and photo.is_file():
                        photo.unlink()
                except OSError:
                    pass

    df = df.loc[~match].copy()
    for column in REPORT_COLUMNS:
        if column not in df.columns:
            df[column] = ""
    df[REPORT_COLUMNS].to_csv(DATA_FILE, index=False)
    return True


# Microsoft Graph can create a real Outlook draft with CC. A standard Outlook
# deeplink cannot reliably set CC. The Graph option requires school-approved
# Microsoft Entra app registration (see OUTLOOK_SETUP.md).
def outlook_graph_config():
    try:
        config = st.secrets.get("outlook_graph", {})
        required = ("tenant_id", "client_id", "client_secret", "redirect_uri")
        return config if all(config.get(key) for key in required) else None
    except (FileNotFoundError, KeyError):
        return None


def outlook_graph_post(url, data, headers=None):
    payload = json.dumps(data).encode("utf-8") if isinstance(data, dict) else urlencode(data).encode("utf-8")
    req = urllib.request.Request(url, data=payload, headers=headers or {}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=18) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        details = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError("Microsoft 365 rejected the request (HTTP " + str(exc.code) + "): " + details[:350]) from exc


def outlook_signed_state(message, config):
    payload = dict(message, issued=int(time.time()))
    encoded = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode()).decode().rstrip("=")
    signature = hmac.new(config["client_secret"].encode(), encoded.encode(), hashlib.sha256).hexdigest()
    return encoded + "." + signature


def outlook_auth_url(message, config):
    state = outlook_signed_state(message, config)
    params = {
        "client_id": config["client_id"], "response_type": "code",
        "redirect_uri": config["redirect_uri"], "response_mode": "query",
        "scope": "openid profile User.Read Mail.ReadWrite",
        "state": state, "prompt": "select_account",
    }
    return "https://login.microsoftonline.com/" + quote(config["tenant_id"], safe="") + "/oauth2/v2.0/authorize?" + urlencode(params)


def outlook_finish_auth(config):
    code = st.query_params.get("code")
    state = st.query_params.get("state")
    if not code or not state:
        return
    try:
        encoded, signature = state.rsplit(".", 1)
        expected = hmac.new(config["client_secret"].encode(), encoded.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, signature):
            raise ValueError("Invalid Outlook sign-in state")
        payload = json.loads(base64.urlsafe_b64decode(encoded + "=" * (-len(encoded) % 4)))
        if abs(time.time() - int(payload["issued"])) > 600:
            raise ValueError("Outlook sign-in expired. Please try again")
        token_endpoint = "https://login.microsoftonline.com/" + quote(config["tenant_id"], safe="") + "/oauth2/v2.0/token"
        token = outlook_graph_post(token_endpoint, {
            "client_id": config["client_id"], "client_secret": config["client_secret"],
            "grant_type": "authorization_code", "code": code,
            "redirect_uri": config["redirect_uri"],
            "scope": "openid profile User.Read Mail.ReadWrite",
        }, {"Content-Type": "application/x-www-form-urlencoded"})
        if not token.get("access_token"):
            raise RuntimeError("Microsoft 365 did not return an access token")
        draft = outlook_graph_post("https://graph.microsoft.com/v1.0/me/messages", {
            "subject": payload["subject"],
            "body": {"contentType": "Text", "content": payload["body"]},
            "toRecipients": [{"emailAddress": {"address": payload["to"]}}],
            "ccRecipients": [{"emailAddress": {"address": payload["cc"]}}],
        }, {"Content-Type": "application/json", "Authorization": "Bearer " + token["access_token"]})
        st.session_state["outlook_ready_draft"] = draft.get("webLink")
        if not st.session_state["outlook_ready_draft"]:
            raise RuntimeError("Draft saved in Outlook but its link was not returned; check Drafts in Outlook")
    except Exception as exc:
        st.session_state["outlook_draft_error"] = str(exc)
    finally:
        # Remove temporary authorization code from the browser address bar.
        st.query_params.clear()
        st.rerun()


def go_home():
    st.session_state.page = "home"
    st.session_state.report_type = None
    st.session_state.selected_item = None


if "page" not in st.session_state:
    st.session_state.page = "home"
if "report_type" not in st.session_state:
    st.session_state.report_type = None
if "selected_item" not in st.session_state:
    st.session_state.selected_item = None

_outlook_config = outlook_graph_config()
if _outlook_config:
    outlook_finish_auth(_outlook_config)
if st.session_state.pop("outlook_draft_error", None):
    st.error("Outlook draft could not be created. Check Microsoft 365 permissions and try again.")
if st.session_state.get("outlook_ready_draft"):
    st.success("Outlook draft created with the correct To, CC, subject and message. Open it to review and send.")
    st.link_button("Open my Outlook draft", st.session_state["outlook_ready_draft"], use_container_width=True)

st.markdown(f"""
<div class="rss-header">
    <img src="data:image/png;base64,{LOGO_DATA}" style="max-width:220px;width:42%;height:auto;margin:0 auto 10px;display:block;">
    <div class="rss-title">Rawd Al Saleheen School Lost & Found</div>
    <div style="margin-top:8px;color:#667085;font-size:15px;">Done by Nour O. Al Sultan</div>
</div>
""", unsafe_allow_html=True)

if st.session_state.page == "home":
    st.markdown('<div class="choice-title">What would you like to do?</div>', unsafe_allow_html=True)
    if st.button("I LOST AN ITEM", use_container_width=True):
        st.session_state.page = "found_items"
        st.rerun()
    if st.button("I FOUND AN ITEM", use_container_width=True):
        # First show missing-item reports so the finder can try to match the item
        # before creating a new found-item report.
        st.session_state.report_type = "Found"
        st.session_state.page = "missing_items"
        st.rerun()
    st.markdown('<div class="home-browse-label">OR BROWSE REPORTS DIRECTLY</div>', unsafe_allow_html=True)
    with st.container(key="home_browse_shortcuts"):
        found_column, missing_column = st.columns(2, gap="small")
        with found_column:
            if st.button("Found Items", use_container_width=True):
                st.session_state.page = "found_items"
                st.rerun()
        with missing_column:
            if st.button("Missing Items", use_container_width=True):
                st.session_state.page = "missing_items"
                st.rerun()

elif st.session_state.page == "found_items":
    st.markdown('<div class="choice-title">Found Items</div>', unsafe_allow_html=True)
    st.markdown('<div class="helper">Check if someone has already found your item.</div>', unsafe_allow_html=True)
    reports = load_reports()
    found = reports[reports["Type"].str.lower() == "found"].copy() if not reports.empty else reports
    search = st.text_input("Search found items", placeholder="Search for an item...")
    if search and not found.empty:
        mask = (found["ItemName"] + " " + found["Description"] + " " + found["Location"]).str.contains(search, case=False, na=False, regex=False)
        found = found[mask]
    if found.empty:
        st.info("No found items match your search yet.")
    else:
        found = found.sort_values("SubmittedAt", ascending=False)
        for _, row in found.iterrows():
            with st.container(border=True, key=f'listing_found_{row["ID"]}'):
                safe_name = html.escape(str(row["ItemName"]))
                safe_building = html.escape(str(row["Building"]))
                safe_location = html.escape(str(row["Location"]))
                safe_description = html.escape(str(row["Description"]))
                st.markdown(f'<div class="listing-name">{safe_name}</div><div class="listing-meta">{safe_building} · {safe_location}</div><div class="listing-description">{safe_description}</div>', unsafe_allow_html=True)
                if st.button("View Details & Contact Finder", key=f'view_{row["ID"]}', use_container_width=True):
                    st.session_state.selected_item = row.to_dict()
                    st.session_state.page = "item_detail"
                    st.rerun()
    with st.container(key="found_report_cta"):
        st.markdown('<div class="report-cta-title">Cannot find your item?</div><div class="report-cta-desc">Submit a missing-item report to help others find it.</div>', unsafe_allow_html=True)
        if st.button("Report Missing Item", use_container_width=True):
            st.session_state.report_type = "Lost"
            st.session_state.page = "form"
            st.rerun()
    if st.button("← Back to Home", key="found_back_home", use_container_width=True):
        go_home()
        st.rerun()

elif st.session_state.page == "missing_items":
    st.markdown('<div class="choice-title">Missing Items</div>', unsafe_allow_html=True)
    st.markdown('<div class="helper">Browse missing items and contact their owners if you found one.</div>', unsafe_allow_html=True)
    reports = load_reports()
    missing = reports[reports["Type"].str.lower() == "lost"].copy() if not reports.empty else reports
    search = st.text_input("Search missing items", placeholder="Search for an item...")
    if search and not missing.empty:
        mask = (missing["ItemName"] + " " + missing["Description"] + " " + missing["Location"]).str.contains(search, case=False, na=False, regex=False)
        missing = missing[mask]
    if missing.empty:
        st.info("No missing items match your search yet.")
    else:
        missing = missing.sort_values("SubmittedAt", ascending=False)
        for _, row in missing.iterrows():
            with st.container(border=True, key=f'listing_missing_{row["ID"]}'):
                safe_name = html.escape(str(row["ItemName"]))
                safe_building = html.escape(str(row["Building"]))
                safe_location = html.escape(str(row["Location"]))
                safe_description = html.escape(str(row["Description"]))
                st.markdown(f'<div class="listing-name">{safe_name}</div><div class="listing-meta">{safe_building} · {safe_location}</div><div class="listing-description">{safe_description}</div>', unsafe_allow_html=True)
                if st.button("View Details / I Found This", key=f'missing_{row["ID"]}', use_container_width=True):
                    st.session_state.selected_item = row.to_dict()
                    st.session_state.page = "item_detail"
                    st.rerun()
    with st.container(key="missing_report_cta"):
        st.markdown('<div class="report-cta-title">Found something not listed?</div><div class="report-cta-desc">Report the item so its owner can find it.</div>', unsafe_allow_html=True)
        if st.button("Report Found Item", use_container_width=True):
            st.session_state.report_type = "Found"
            st.session_state.page = "form"
            st.rerun()
    if st.button("← Back to Home", key="missing_back_home", use_container_width=True):
        go_home()
        st.rerun()

elif st.session_state.page == "item_detail":
    item = st.session_state.selected_item
    if not item:
        st.session_state.page = "found_items"
        st.rerun()
    contact_email = str(item.get("Email", "")).strip()
    is_lost_item = str(item.get("Type", "")).strip().lower() == "lost"
    st.markdown(f'<div class="detail-heading">{html.escape(str(item.get("ItemName", "Item")))}</div>', unsafe_allow_html=True)
    st.markdown(f'<div class="detail-subheading">{"Missing item details" if is_lost_item else "Found item details"}</div>', unsafe_allow_html=True)
    photo_path = item.get("Photo", "")
    if is_lost_item and photo_path and Path(photo_path).exists():
        st.image(photo_path, use_container_width=True)

    place_label = "Last seen at" if is_lost_item else "Found at"
    date_label = "Date lost" if is_lost_item else "Date found"
    building = str(item.get("Building", "")).strip()
    location = str(item.get("Location", "")).strip()
    grade_level = str(item.get("GradeLevel", "")).strip()
    school_class = str(item.get("Class", "")).strip()
    date_found = str(item.get("EventDate", "")).strip()
    description = str(item.get("Description", "")).strip()

    # Display related information together; escape all report text before embedding in HTML.
    def safe_detail(value):
        return html.escape(value) if value and value.lower() != "nan" else "—"

    def field(label, value, extra_class="", secondary=""):
        secondary_html = ('<div class="detail-info-secondary">' + safe_detail(secondary) + '</div>') if secondary else ""
        return ('<div class="detail-info-field ' + extra_class + '">'
                '<div class="detail-info-label">' + html.escape(label) + '</div>'
                '<div class="detail-info-value">' + safe_detail(value) + '</div>'
                + secondary_html + '</div>')

    class_details = " · ".join(x for x in (grade_level, school_class) if x and x.lower() != "nan")
    detail_card = (
        '<div class="detail-info-card"><div class="detail-info-grid">'
        + field("Building", building)
        + field(place_label, location, secondary=class_details)
        + field(date_label, date_found)
        + field("Description", description, "detail-info-field-wide")
        + '</div></div>'
    )
    st.markdown(detail_card, unsafe_allow_html=True)

    mail_svg = ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" '
                'fill="none" stroke="currentColor" stroke-width="1.8" '
                'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
                '<rect x="2" y="4" width="20" height="16" rx="2"/>'
                '<path d="m3 6 9 7 9-7"/></svg>')

    if contact_email:
        st.markdown("### I Found This Item" if is_lost_item else "### Contact the Finder")
        if is_lost_item:
            st.markdown('<p class="detail-intro">Found this item? Contact the student using your RSS school email.</p>', unsafe_allow_html=True)
            email_subject = "RSS Lost & Found - " + str(item.get("ItemName", "Item"))
            email_body = ("Hello, I found an item that may belong to you. "
                          "Please email me the color of your bottle to help confirm it is yours."
                          if "bottle" in str(item.get("ItemName", "")).lower()
                          else "Hello, I found an item that may belong to you. "
                               "Please email me the color of your item to help confirm it is yours.")
        else:
            st.markdown('<p class="detail-intro">Think this is yours? Email the finder and mention your item&#39;s color to help confirm ownership.</p>', unsafe_allow_html=True)
            email_subject = "RSS Lost & Found - " + str(item.get("ItemName", "Item"))
            email_body = "Hello, I think this item belongs to me. The color of my item is: "

        email_cc = "1730@rawdalsaleheen.edu.kw"
        if email_cc and _outlook_config:
            # Creates a real draft in the student's OWN school mailbox. CC is
            # a proper ccRecipients field, not an unsupported URL parameter.
            auth_url = outlook_auth_url({
                "to": str(contact_email).strip(), "cc": email_cc,
                "subject": email_subject, "body": email_body,
            }, _outlook_config)
            st.markdown('<a class="detail-email-button" href="' + html.escape(auth_url, quote=True) + '">' + mail_svg + 'Prepare Email in Outlook</a>', unsafe_allow_html=True)
            st.caption("Sign in with your RSS school account. Outlook will create a draft with To, CC, subject and message ready for you to review and send.")
        else:
            # Fallback is intentionally honest: Outlook's basic web link does
            # NOT reliably set actual CC. Keep the existing working link.
            compose_params = {"to": str(contact_email).strip(), "subject": email_subject, "body": email_body}
            mail_href = "https://outlook.office.com/mail/0/deeplink/compose?" + urlencode(compose_params, quote_via=quote)
            st.markdown('<a class="detail-email-button" target="_blank" rel="noopener noreferrer" href="' + html.escape(mail_href, quote=True) + '">' + mail_svg + 'Email the ' + ('Student' if is_lost_item else 'Finder') + ' in Outlook</a>', unsafe_allow_html=True)
            if email_cc:
                st.info("Please add the email below in Outlook's CC field before sending ↓")
                st.code(email_cc, language=None)
        with st.expander("Email not filled in? Copy the details here", expanded=False):
            st.markdown("**To**")
            st.code(str(contact_email), language=None)
            if email_cc:
                st.markdown("**CC**")
                st.code(email_cc, language=None)
            st.markdown("**Subject**")
            st.code(email_subject, language=None)
            st.markdown("**Message**")
            st.code(email_body, language=None)

    if contact_email:
        with st.expander("Administrator · Item Returned?", expanded=False):
            st.markdown('<div class="detail-intro">Item returned? Enter the administrator password to mark it as resolved.</div>', unsafe_allow_html=True)
            item_id = str(item.get("ID", ""))
            confirm_key = f"confirm_resolve_{item_id}"
            verified_key = f"verified_resolve_{item_id}"
            attempts_key = f"resolve_attempts_{item_id}"
            lock_key = f"resolve_locked_until_{item_id}"

            if not st.session_state.get(verified_key, False):
                with st.form(f"resolve_password_form_{item_id}"):
                    resolve_password = st.text_input("Administrator password", type="password", key=f"resolve_password_{item_id}")
                    unlock = st.form_submit_button("UNLOCK MARK AS RESOLVED", use_container_width=True)
                if unlock:
                    if time.time() < st.session_state.get(lock_key, 0):
                        st.error("Too many attempts. Please wait 5 minutes before trying again.")
                    elif valid_resolve_password(resolve_password):
                        st.session_state[verified_key] = True
                        st.session_state[attempts_key] = 0
                        st.rerun()
                    else:
                        attempts = st.session_state.get(attempts_key, 0) + 1
                        st.session_state[attempts_key] = attempts
                        if attempts >= 5:
                            st.session_state[lock_key] = time.time() + 300
                            st.session_state[attempts_key] = 0
                            st.error("Too many attempts. Please wait 5 minutes before trying again.")
                        else:
                            st.error("Incorrect administrator password.")
            elif not st.session_state.get(confirm_key, False):
                if st.button("MARK AS RESOLVED", use_container_width=True, key=f"resolve_start_{item_id}"):
                    st.session_state[confirm_key] = True
                    st.rerun()
            else:
                st.markdown('<div style="background:#D1D5DB; color:#FFFFFF; padding:0.85rem 1rem; border-radius:8px; font-weight:700; margin:0.5rem 0 1rem 0;">Are you sure this item has been returned to its owner?</div>', unsafe_allow_html=True)
                confirm_col, cancel_col = st.columns(2)
                with confirm_col:
                    if st.button("YES, MARK AS RESOLVED", use_container_width=True, key=f"resolve_yes_{item_id}"):
                        # Verify the per-item unlock state before allowing deletion.
                        if st.session_state.get(verified_key, False) and resolve_report(item_id):
                            st.session_state.pop(confirm_key, None)
                            st.session_state.pop(verified_key, None)
                            st.session_state.selected_item = None
                            st.session_state.page = "resolved"
                            st.rerun()
                        else:
                            st.error("This report could not be removed. Please try again.")
                with cancel_col:
                    if st.button("CANCEL", use_container_width=True, key=f"resolve_cancel_{item_id}"):
                        st.session_state.pop(confirm_key, None)
                        st.session_state.pop(verified_key, None)
                        st.rerun()

    back_label = "Back to Missing Items" if is_lost_item else "Back to Found Items"
    if st.button("← " + back_label, use_container_width=True, key="detail_back"):
        st.session_state.page = "missing_items" if is_lost_item else "found_items"
        st.rerun()

elif st.session_state.page == "resolved":
    st.markdown("""
    <div class="success-box">
        <h2 style="color:#102a52;margin-top:0;">Item Resolved</h2>
        <p style="color:#667085;margin-bottom:0;">The report has been removed from the active Lost & Found listings.</p>
    </div>
    """, unsafe_allow_html=True)
    st.write("")
    if st.button("Back to Home", use_container_width=True, key="resolved_home"):
        go_home()
        st.rerun()

elif st.session_state.page == "form":
    report_type = st.session_state.report_type
    action = "lost" if report_type == "Lost" else "found"
    st.markdown(f'<div class="choice-title">Report a {report_type} Item</div>', unsafe_allow_html=True)

    # Start with no preselected building/place so a shared link opens cleanly.
    building = st.selectbox(
        "Building *",
        BUILDINGS,
        index=None,
        placeholder="Select a building",
        help="Choose the school building where the item was lost or found.",
    )

    grade_level = ""
    class_name = ""
    location = ""
    custom_location = ""

    # Place comes directly after Building. Grade Level and Class only appear
    # when Classroom is selected in the Girls or Boys building.
    if building == "Girls Building":
        location_options = ["Classroom"] + GIRLS_SPECIAL_LOCATIONS + ["Other"]
    elif building == "Boys Building":
        location_options = ["Classroom"] + BOYS_SPECIAL_LOCATIONS + ["Other"]
    elif building == "Administration Building":
        location_options = ADMIN_LOCATIONS + ["Other"]
    else:
        location_options = []

    if building:
        location_choice = st.selectbox(
            "Place *",
            location_options,
            index=None,
            placeholder="Select a place",
            help="Choose the exact place where the item was lost or found.",
        )

        if location_choice == "Classroom" and building in ["Girls Building", "Boys Building"]:
            grade_level = st.selectbox(
                "Grade Level *",
                GRADE_LEVELS,
                index=None,
                placeholder="Select a grade level",
            )
            if grade_level:
                if building == "Girls Building":
                    class_map = {
                        "High School": GIRLS_HIGH_SCHOOL,
                        "Middle School": GIRLS_MIDDLE_SCHOOL,
                        "Elementary School": GIRLS_ELEMENTARY,
                    }
                else:
                    class_map = {
                        "High School": BOYS_HIGH_SCHOOL,
                        "Middle School": BOYS_MIDDLE_SCHOOL,
                        "Elementary School": BOYS_ELEMENTARY,
                    }
                class_name = st.selectbox(
                    "Class *",
                    class_map[grade_level],
                    index=None,
                    placeholder="Select a class",
                ) or ""

        if location_choice == "Other":
            custom_location = st.text_input(
                "Other place *",
                placeholder="Type the place",
                help="Enter the place if it is not listed above.",
            )
            location = custom_location.strip()
        else:
            location = location_choice or ""

    with st.form("rss_report_form", clear_on_submit=False):
        st.info("Do NOT include the item's color in its name or description. The color must stay private so the owner can confirm it by email.")
        item_name = st.text_input("Item name *", placeholder="What item was lost or found?")
        description = st.text_area("Description *", placeholder="Describe the item, including its brand, size, or other useful details.", height=100)
        event_date = st.date_input(f"Date it was {action} *", value=date.today(), max_value=date.today())
        email = st.text_input("Your RSS email *", placeholder="Email e.g. 1730@rawdalsaleheen.edu.kw", help="Write your RSS email here. It is required so someone can contact you through Outlook. Your name is not displayed.")
        photo = st.file_uploader("Photo (optional)", type=["png", "jpg", "jpeg"], help="Upload a clear photo of the item if you have one.") if report_type == "Lost" else None
        submitted = st.form_submit_button("Submit Report", use_container_width=True)

        if submitted:
            classroom_selected = location_choice == "Classroom" if building else False
            missing_school_info = classroom_selected and (not grade_level or not class_name.strip())
            missing_other_place = building and location_choice == "Other" and not custom_location.strip()
            if not building or not location or not item_name.strip() or not description.strip() or missing_school_info or missing_other_place:
                st.error("Please complete all required fields.")
            elif not valid_rss_email(email):
                st.error("Please enter a valid RSS email ending with @rawdalsaleheen.edu.kw.")
            else:
                report = {
                    "ID": uuid.uuid4().hex,
                    "Type": report_type,
                    "Building": building,
                    "ItemCategory": "",
                    "GradeLevel": grade_level or "",
                    "Class": class_name.strip(),
                    "ItemName": item_name.strip(),
                    "Description": description.strip(),
                    "Location": location.strip(),
                    "EventDate": event_date.isoformat(),
                    "Email": email.strip().lower(),
                    "Photo": "",
                    "SubmittedAt": datetime.now().isoformat(timespec="seconds"),
                }
                save_report(report, photo)
                st.session_state.page = "success"
                st.rerun()

    if st.button("Back", use_container_width=True):
        go_home()
        st.rerun()

elif st.session_state.page == "success":
    st.markdown("""
    <div class="success-box">
        <h2 style="color:#102a52;margin-top:0;">Report Submitted</h2>
        <p style="color:#667085;margin-bottom:0;">Your report has been recorded.</p>
    </div>
    """, unsafe_allow_html=True)
    st.write("")
    if st.button("Back to Home", use_container_width=True):
        go_home()
        st.rerun()
